﻿syntax = "proto3";

message PersonInfoMessageWrapper {
  // Version number for the message format.
    oneof versions {
        PersonInfoMessageV1 v1 = 1;
    }

    message PersonInfoMessageV1 {
        repeated Identity identities = 1;
        int32 accountId = 2;
        int32 storeId = 3;
        int32 clusteringVersion = 4;

        message Identity {
            // List of objects, each containing photoId, modelVersion, and embedding.
            int32 identityNumeralId = 1;
            PersonInfo personInfo = 2;

            message PersonInfo {
                repeated ImageInfo imagesInfo =1;
                float age = 2;
                int32 gender = 3;
				int64 bestPhoto = 4;
            }

			message ImageInfo {
                int64 photoId=1;
                BBox faceBbox=6;
            }

            message BBox {
                float x1=1;
                float y1=2;
                float x2=3;
                float y2=4;
            }

        }
    }
}

