message PairConnectivityMessageWrapper {
  // Version number for the message format.
    oneof versions {
        PairConnectivityMessageV1 v1 = 1;
    }

    message PairConnectivityMessageV1 {
        repeated PairInfo pairs = 1;
        int32 accountId = 2;
        int32 storeId = 3;

        message PairInfo {
            int32 personId1 = 1;
            int32 personId2 = 2;
            float connectivity = 3;
            int32 connectionNumber = 4;
        }
    }
}
